def _bundle_decode(_blob):
    return _zlibmod.decompress(_b64mod.b64decode(_blob))


def dump_extra_sources(target_dir="."):
    """Write the optional bundled sources (skilluse.py, join_spam_manager.py,
    dc.py) to disk. They are shipped for completeness but never imported by
    the running bot, so they cannot destabilise it."""
    _written = []
    for _nm, _blb in _EXTRA_B64.items():
        try:
            _data = _bundle_decode(_blb)
            _out = os.path.join(target_dir, _nm)
            with open(_out, "wb") as _fh:
                _fh.write(_data)
            _written.append(_out)
        except Exception as _e:
            print("dump_extra_sources warning:", _nm, _e)
    return _written


def _materialize_pb2():
    """Write the embedded *_pb2.py descriptors to a temp package dir."""
    try:
        _root = os.path.join(_tempmod.gettempdir(), "shappno_pb2_runtime")
        _pkg = os.path.join(_root, "Pb2")
        os.makedirs(_pkg, exist_ok=True)
        _initf = os.path.join(_pkg, "__init__.py")
        if not os.path.exists(_initf):
            with open(_initf, "w", encoding="utf-8") as _fh:
                _fh.write("")
        for _nm, _blb in _PB2_B64.items():
            _pf = os.path.join(_pkg, _nm + ".py")
            try:
                _src = _bundle_decode(_blb)
            except Exception:
                continue
            if (not os.path.exists(_pf)) or os.path.getsize(_pf) != len(_src):
                with open(_pf, "wb") as _fh:
                    _fh.write(_src)
        if _root not in sys.path:
            sys.path.insert(0, _root)
    except Exception as _e:
        print("pb2 bootstrap warning:", _e)


_materialize_pb2()

