def get_player_status(packet):
    j = get_available_room(packet)
    if not j:
        return "OFFLINE"
    p = json.loads(j)
    try:
        data = p["5"]["data"]["1"]["data"]
        st   = data["3"]["data"]
        if st == 1:
            return "SOLO"
        if st == 2:
            if "9" in data and "data" in data["9"]:
                gc = data["9"]["data"]
                mx = data["10"]["data"] + 1
                return f"INSQUAD ({gc}/{mx})"
            return "INSQUAD"
        if st in (3, 5):
            return "INGAME"
        if st == 4:
            return "IN ROOM"
        if st in (6, 7):
            return "IN SOCIAL ISLAND MODE"
        return "NOTFOUND"
    except Exception:
        return "OFFLINE"


