async def OpEnSq(K, V, region):
    fields = {
        1: 1,
        2: {
            2: "\u0001", 3: 1, 4: 1, 5: "en",
            9: 1, 11: 1, 13: 1,
            14: {2: 5756, 6: 11, 8: "1.111.5", 9: 2, 10: 4}
        }
    }
    if region.lower() == "ind":
        packet = '0514'
    elif region.lower() == "bd":
        packet = "0519"
    else:
        packet = "0515"
    return await GeneRaTePk((await CrEaTe_ProTo(fields)).hex(), packet, K, V)


