REGION_PREF = os.environ.get("REGION", "BD")

def load_credentials(filename="SHAPPNO.txt"):
    """Env-var first, SHAPPNO.txt fallback. Never crashes at import time."""
    values = {}
    try:
        with open(filename, "r", encoding="utf-8") as credential_file:
            for raw_line in credential_file:
                line = raw_line.strip()
                if not line or line.startswith("#") or "=" not in line:
                    continue
                key, value = line.split("=", 1)
                values[key.strip().upper()] = value.strip()
    except FileNotFoundError:
        pass

    uid = (os.environ.get("BOT_UID", "") or values.get("UID", "")).strip()
    password = (os.environ.get("BOT_PASSWORD", "") or values.get("PASSWORD", "")).strip()
    if not uid or not password:
        print("WARNING: BOT_UID / BOT_PASSWORD not configured (env vars or SHAPPNO.txt).")
        uid = uid or "0"
        password = password or "0"
    return uid, password

BOT_UID, BOT_PASSWORD = load_credentials()
