def _clean_game_text(text):
    """Convert in-game colour markup into plain Telegram-safe text."""
    if text is None:
        return ""
    s = str(text)
    s = _TAG_RE.sub("", s)
    s = s.replace("\\n", "\n")
    return s.strip()


