def _kb(key):
    title, items = MENUS.get(key, MENUS["main"])
    rows = []
    for label, action in items:
        rows.append([InlineKeyboardButton(label, callback_data=action)])
    return title, InlineKeyboardMarkup(rows)


async def _show_menu(update, key, edit=False):
    title, markup = _kb(key)
    text = f"<b>{title}</b>\n\nاختر من الأزرار أدناه، أو أرسل أي أمر مباشرة."
    if edit and update.callback_query:
        try:
            await update.callback_query.edit_message_text(text, reply_markup=markup, parse_mode="HTML")
            return
        except Exception:
            pass
    await update.effective_chat.send_message(text, reply_markup=markup, parse_mode="HTML")


async def cmd_start(update: "Update", context: "ContextTypes.DEFAULT_TYPE"):
    try:
        _LAST_CHAT_ID["id"] = update.effective_chat.id
    except Exception:
        pass
    await _show_menu(update, "main")


async def cmd_menu(update: "Update", context: "ContextTypes.DEFAULT_TYPE"):
    try:
        _LAST_CHAT_ID["id"] = update.effective_chat.id
    except Exception:
        pass
    await _show_menu(update, "main")


async def on_callback(update: "Update", context: "ContextTypes.DEFAULT_TYPE"):
    q = update.callback_query
    try:
        await q.answer()
    except Exception:
        pass
    try:
        _LAST_CHAT_ID["id"] = update.effective_chat.id
    except Exception:
        pass
    data = q.data or ""
    if data.startswith("menu:"):
        await _show_menu(update, data.split(":", 1)[1], edit=True)
        return
    if data.startswith("run:"):
        cmd = data.split(":", 1)[1]
        if not _is_tg_admin(update):
            await q.message.reply_text("⛔ غير مصرح لك.")
            return
        if TG_QUEUE is not None:
            await TG_QUEUE.put(cmd)
        await q.message.reply_text(f"⏳ تم إرسال الأمر: <code>{_htmlmod.escape(cmd)}</code>", parse_mode="HTML")
        return
    if data.startswith("ask:"):
        template = data.split(":", 1)[1]
        await q.message.reply_text(
            "✍️ أرسل الأمر كاملاً بهذا الشكل:\n"
            f"<code>{_htmlmod.escape(template)}</code>\n\n"
            "استبدل القيم داخل &lt;&gt; بالقيم المطلوبة.",
            parse_mode="HTML",
        )
        return
    await _show_menu(update, "main", edit=True)


async def on_text(update: "Update", context: "ContextTypes.DEFAULT_TYPE"):
    if not update.message or not update.message.text:
        return
    try:
        _LAST_CHAT_ID["id"] = update.effective_chat.id
    except Exception:
        pass
    text = update.message.text.strip()
    if not text:
        return
    if not _is_tg_admin(update):
        await update.message.reply_text("⛔ غير مصرح لك باستخدام هذا البوت.")
        return
    if TG_QUEUE is not None:
        await TG_QUEUE.put(text)
    await update.message.reply_text(
        f"⏳ تم تنفيذ: <code>{_htmlmod.escape(text)}</code>", parse_mode="HTML"
    )


async def cmd_help(update: "Update", context: "ContextTypes.DEFAULT_TYPE"):
    await _show_menu(update, "main")


async def _tg_sink(message):
    """Forward an in-game reply to the Telegram admin chat."""
    chat_id = _LAST_CHAT_ID.get("id") or 0
    if not chat_id:
        return
    text = _clean_game_text(message)
    if not text:
        return
    if len(text) > 3900:
        text = text[:3900] + "…"
    try:
        await _TG_APP.bot.send_message(chat_id=chat_id, text=text)
    except Exception:
        pass


_TG_APP = None


async def _start_telegram():
    global _TG_APP, TG_SINK
    if not _PTB_OK:
        print("Telegram layer disabled (library missing).")
        return None
    if not TELEGRAM_TOKEN:
        print("TELEGRAM_BOT_TOKEN not set — Telegram layer disabled.")
        return None
    try:
        app = Application.builder().token(TELEGRAM_TOKEN).build()
        app.add_handler(CommandHandler("start", cmd_start))
        app.add_handler(CommandHandler("menu", cmd_menu))
        app.add_handler(CommandHandler("help", cmd_help))
        app.add_handler(CallbackQueryHandler(on_callback))
        app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND, on_text))
        app.add_handler(MessageHandler(filters.COMMAND, on_text))
        await app.initialize()
        await app.start()
        await app.updater.start_polling(drop_pending_updates=True)
    except Exception as _e:
        print("Telegram layer failed to start:", _e)
        return None
    _TG_APP = app
    TG_SINK = _tg_sink
    print("Telegram control layer started.")
    return app


async def _health_server():
    """Tiny HTTP health endpoint so Railway (and any PaaS) sees a live port."""
    _port = os.environ.get("PORT", "").strip()
    if not _port:
        return None
    try:
        from aiohttp import web

        async def _ok(request):
            return web.Response(text="SHAPPNO Telegram bot is alive")

        _app = web.Application()
        _app.router.add_get("/", _ok)
        _app.router.add_get("/health", _ok)
        _runner = web.AppRunner(_app)
        await _runner.setup()
        _site = web.TCPSite(_runner, "0.0.0.0", int(_port))
        await _site.start()
        print(f"Health server listening on 0.0.0.0:{_port}")
        return _runner
    except Exception as _e:
        print("health server warning:", _e)
        return None


async def _amain():
    global TG_QUEUE
    TG_QUEUE = asyncio.Queue()
    health = await _health_server()
    tg_app = await _start_telegram()
    engine_task = asyncio.create_task(StarTinG())
    try:
        await engine_task
    except asyncio.CancelledError:
        pass
    finally:
        if tg_app is not None:
            try:
                await tg_app.updater.stop()
                await tg_app.stop()
                await tg_app.shutdown()
            except Exception:
                pass
        if health is not None:
            try:
                await health.cleanup()
            except Exception:
                pass


if __name__ == "__main__":
    try:
        asyncio.run(_amain())
    except KeyboardInterrupt:
        print("\nBot stopped.")

